#include "raid/source.hpp"
#include "raid/layout.hpp"
#include "raid/json.hpp"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <sstream>
int main(int argc,char**argv){std::string level_s,members_s,out,export_p;std::uint32_t stripe=128;std::uint64_t off=0,n=0;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--level"&&i+1<argc)level_s=argv[++i];else if(a=="--stripe"&&i+1<argc)stripe=std::stoul(argv[++i]);else if(a=="--members"&&i+1<argc)members_s=argv[++i];else if(a=="--output"&&i+1<argc)out=argv[++i];else if(a=="--export"&&i+1<argc)export_p=argv[++i];else if(a=="--offset"&&i+1<argc)off=std::stoull(argv[++i]);else if(a=="--size"&&i+1<argc)n=std::stoull(argv[++i]);else{std::cerr<<"usage: raidscan --level 0|1|5|6|10|linear --stripe sectors --members a,b,,d [--output report.json] [--export file --offset N --size N]\n";return 2;}}if(members_s.empty()||level_s.empty()){std::cerr<<"level and members required\n";return 2;}raid::Level l;if(level_s=="0")l=raid::Level::R0;else if(level_s=="1")l=raid::Level::R1;else if(level_s=="5")l=raid::Level::R5;else if(level_s=="6")l=raid::Level::R6;else if(level_s=="10")l=raid::Level::R10;else l=raid::Level::Linear;std::vector<raid::Member>ms;std::vector<std::unique_ptr<raid::ISource>>ss;std::stringstream st(members_s);std::string p;std::uint32_t idx=0;while(std::getline(st,p,',')){raid::Member m{};m.index=idx++;m.path=p;if(p.empty()){m.missing=true;m.size=0;ms.push_back(m);ss.push_back(nullptr);continue;}std::string e;auto s=raid::open_source(p,e);if(!s){std::cerr<<e<<"\n";return 3;}m.size=s->size();ms.push_back(m);ss.push_back(std::move(s));}if(ms.empty()){std::cerr<<"no members\n";return 2;}auto lay=raid::make_layout(l,stripe,ms);raid::Result r{};r.status="configured";r.layout=lay;r.members=ms;if(std::count_if(ms.begin(),ms.end(),[](auto&m){return m.missing;})>0)r.warnings.push_back("degraded array: missing member placeholder present");if(l==raid::Level::R6)r.warnings.push_back("RAID6 baseline reports geometry but full Reed-Solomon reconstruction is a commercial release gate");if(l==raid::Level::R10)r.warnings.push_back("RAID10 baseline exposes layout model; vendor-specific near/far/offset variants require plugins");if(!export_p.empty()){if(n==0)n=lay.logical_size-off;std::string e;if(!raid::export_virtual(lay,ss,off,n,export_p,e)){std::cerr<<e<<"\n";return 4;}}auto j=raid::json(r);if(out.empty())std::cout<<j<<"\n";else{std::ofstream f(out);if(!f){std::cerr<<"cannot write report\n";return 5;}f<<j;}return 0;}
